final AtomicReference<Balances> state = new AtomicReference<>(Balances.empty());

boolean transfer(int from, int to, long amt) {
    for (;;) {
        Balances cur = state.get();               // single reference read = our snapshot
        long f = cur.get(from), t = cur.get(to);
        if (f < amt) return false;
        Balances next = cur.with(from, f - amt).with(to, t + amt);
        if (state.compareAndSet(cur, next)) return true;   // commit in one step
        // conflict: whole block replays against the new snapshot
    }
}

/* multi-location read that must not be torn: take the reference once,
   read every field from that one object, never from state.get() again. */
